function projectPage(project){const first=Math.max(0,project.slides.findIndex(slide=>slide[2]==='video'));const [initialSrc,initialCaption,initialType,initialPoster]=project.slides[first];const initialMedia=initialType==='video'?`<video id="project-video" autoplay loop controls muted playsinline preload="metadata" poster="${initialPoster}" aria-label="${initialCaption}"><source src="${initialSrc}" type="video/mp4"></video>`:`<img id="project-image" src="${initialSrc}" alt="${initialCaption}">`;return `<article class="story-project" aria-labelledby="project-title"><aside class="project-introduction"><a class="text-link project-back" href="/stories/">← Blog</a><p class="eyebrow">${project.label}</p><h1 id="project-title">${project.title}</h1><p class="project-lead">${project.intro}</p>${project.paragraphs.map(t=>`<p>${t}</p>`).join('')}${project.note?`<p class="project-note">${project.note}</p>`:''}<p class="story-contact">If you would like to get in touch directly, please send me an <a href="https://outlook.live.com/mail/0/deeplink/compose?to=yoe18271%40outlook.com" target="_blank" rel="noopener">email</a>, or follow my <a href="https://www.instagram.com/yufloto/" target="_blank" rel="noopener">Instagram</a> for regular updates!</p></aside><section class="project-sequence" tabindex="0" aria-label="Photographic sequence"><figure class="project-frame"><div id="project-media">${initialMedia}</div><figcaption id="project-caption" aria-live="polite">${initialCaption}</figcaption></figure><div class="project-navigation"><button type="button" data-project-step="-1" aria-label="Previous photograph">←</button><span>Take your time. Look a little closer.</span><button type="button" data-project-step="1" aria-label="Next photograph">→</button></div><div class="project-thumbnails">${project.slides.map(([src,caption,type,poster],i)=>`<button type="button" data-project-index="${i}" aria-label="${caption}" aria-current="${i===first}">${type==='video'?`<span class="video-thumb" aria-hidden="true"><img src="${poster}" alt=""><span>▶</span></span>`:`<img src="${src}" alt="" loading="lazy">`}</button>`).join('')}</div></section></article>`}
const journey=projectPage(storyProjects['finding-my-way-back']);
const illustrationWorks=[["Cats in 2025", "yui-cats-illustration.jpg"], ["Love is universal", "illustration-love.jpg"], ["Another way of seeing", "illustration-perspective.jpg"], ["A quiet green", "illustration-quiet.jpg"], ["Reaching for the sun", "illustration-bloom.jpg"], ["Through the green", "illustration-forest.jpg"], ["A Witch’s Feast", "illustration-witch-feast.jpg"]];
const about=`<div class="about-journal about-reference"><section class="reference-about"><div class="reference-biography"><h1 class="about-top-label">A bit about me</h1><div class="biography-photo">${homeImage('yui-drawing','Yui drawing at her desk')}</div><p>I’m Yui (Yi Yu), a travelling photographer, now making a life in Auckland, New Zealand.</p><p>I’m happiest wandering with my Fujifilm, following natural light and noticing what’s happening around me — a passing expression, a conversation, a scene I might otherwise have walked past.</p><p>I’m drawn to the feeling between people as much as the people themselves. An unexpected laugh. A moment of stillness. The energy that changes when someone feels at ease.</p><p>Travel, long walks, independent films, photography books, and art exhibitions all find their way into how I see. I like coming away with something new to notice.</p><p>My work moves between portraits, street photography, events, and behind the scenes. I’m also exploring short films and visual storytelling.</p><p>I hope the photographs keep a little of the moment’s energy — its warmth, freedom, or quiet — so you can return to the feeling.</p><a class="text-link" href="/stories/finding-my-way-back/">How I found my way into photography</a></div><div class="personal-photo-cloud"><figure class="cloud-camera"><video autoplay loop controls muted playsinline preload="metadata" poster="/assets/yui-3268.jpg" aria-label="A little moment with Yui"><source src="/assets/yui-213-two.mp4" type="video/mp4"></video></figure><figure class="cloud-drawing">${photo('about-street-alternate','Yui wandering beneath the trees')}</figure><figure class="cloud-cat">${homeImage('yui-cat','A small moment with a cat')}</figure><figure class="cloud-street">${homeImage('yui-blue','Yui holding a blue illustration')}</figure><figure class="cloud-portrait">${homeImage('yui-bus','Yui pausing by a bus')}</figure><figure class="cloud-art">${photo('about-grass','Yui sitting in the green grass')}</figure><figure class="cloud-window">${photo('about-art','Yui holding a painting')}</figure></div></section><section class="illustration-section" aria-labelledby="illustration-title"><div class="illustration-heading"><div><p class="eyebrow">A SOFT SPOT FOR LITTLE THINGS</p><h2 id="illustration-title">Another way of seeing.</h2><p class="infp-copy">I have a soft spot for cats, drawing, and getting a little lost in nature. I love sincere conversations and the quiet feeling of really connecting with someone. Drawing is another way I make room for the things I care about.</p></div><div class="carousel-arrows"><button type="button" id="art-pause" aria-label="Pause illustration slideshow" aria-pressed="false">Ⅱ</button><button type="button" data-art-direction="-1" aria-label="Previous illustrations">←</button><button type="button" data-art-direction="1" aria-label="Next illustrations">→</button></div></div><div class="illustration-track" tabindex="0" aria-label="Illustrations by Yui; scroll horizontally">${illustrationWorks.map(([title,file])=>`<figure><img src="/assets/${file}" alt="${title}, an illustration by Yui" loading="eager"><figcaption>${title}</figcaption></figure>`).join('')}</div></section><section class="about-actions" aria-label="Explore more"><a href="/pricing/">Pricing + more</a><a href="/portfolio/">Portfolio</a><a href="/contact/">Inquire</a></section></div>`;
const portfolio=`<div class="page-heading portfolio-heading"><p class="eyebrow">The portfolio</p><h1>Where the light leads.</h1><p>Following light through faces, places, and the life between — holding onto what moves, what connects, and the small details that touch us.</p></div><div class="portfolio-toolbar"><div class="filters" aria-label="Filter photographs">${['All','Portraits','Pets','Events','Brand & Lifestyle'].map((c,i)=>`<button data-filter="${c}" class="${i===0?'active':''}" aria-pressed="${i===0}">${c==='Events'?'Events/BTS':c}</button>`).join('')}</div></div><div class="portfolio photo-wall" id="gallery">${portfolioPhotos.map(p=>`<button data-cat="${p.category}" data-photo="${p.id}" class="wall-card" aria-label="Open ${p.title}"><span class="wall-image" style="aspect-ratio:${p.width}/${p.height}"><img src="/assets/${p.id}-thumb.jpg" alt="${p.alt}" width="${p.width}" height="${p.height}" loading="lazy" decoding="async"></span><span class="wall-meta"><span>${p.title}</span><span class="wall-category">${p.category==='Events'?'Events/BTS':p.category}</span></span></button>`).join('')}<p class="empty" hidden>This collection is still growing.</p></div>${banner}`;
const stories=`<div class="page-heading blog-heading"><p class="eyebrow">Blog</p><h1>A little closer.</h1><p>Stories from behind my camera. Beginning with my own journey — with stories of cats and the people I photograph still to come.</p></div><section class="section blog-section"><div class="journal blog-journal"><a href="/stories/finding-my-way-back/" class="story-card"><div class="photo">${photo('blog-img6217','Yui resting in the grass beneath a wide blue sky')}</div><p class="eyebrow" style="margin-top:22px">Personal story / My photography journey</p><h2>Finding my <em>way back.</em></h2><p>From my first camera to finding my own way of seeing.</p><span class="text-link">Read my story</span></a></div></section>`;
const service=(id,kicker,title,copy)=>`<section class="price-block split"><div class="photo">${photo(id,title)}</div><div class="copy"><p class="eyebrow">${kicker}</p><h2>${title}</h2><p>${copy}</p><p class="price-label">Please inquire for pricing</p>${button('Let’s plan your session','contact')}</div></section>`;
const pricing=`<div class="page-heading"><p class="eyebrow">Pricing &amp; experience</p><h1>For the moments<br>you want to keep.</h1><p>Start with what matters to you. We’ll shape the photographs around that.</p></div><div class="section pricing-services" style="padding-top:0">${service('R0001868','01 / Couples & connections','Time, together.','A walk, the sea, or a place you both love. Space for the small gestures and shared moments that make a connection yours.')}${service('DSCF2091','02 / People & pets','The ones with<br>paws, too.','Pet portraits and photographs with the companions who are part of your everyday life. Tell me about their personality and the places they feel at home.')}${service('DSCF2319','03 / Portraits','A little time<br>for you.','Personal portraits, a favourite place, and photographs that feel like your own kind of presence.')}<section class="price-block pricing-events"><div class="split"><div class="copy"><p class="eyebrow">04 / Events & brands</p><h2>People, atmosphere,<br>and your next idea.</h2><p>Event photography, brand photographs, short videos, and content for social media. Share your brief and the kind of support you need.</p><p class="price-label">Quoted to suit your project</p>${button('Share your brief','contact')}</div><div class="pricing-support"><h3>Content Creation &amp;<br>Social Media Support</h3><p>Photography · Reels · Captions<br>Content planning · Scheduling</p><p class="note">The scope is agreed for each project.</p></div></div></section></div><section class="section soft"><div class="faq"><p class="eyebrow">A few things you might be wondering</p><h2>Before we begin.</h2><details><summary>What happens after I get in touch?</summary><p>We’ll talk about the type of session, your preferred date and location, and the photographs you have in mind. Your quote will set out the session and delivery details.</p></details><details><summary>What if I feel awkward in front of the camera?</summary><p>You don’t need to arrive knowing how to pose. Tell me how you feel, and we can plan a setting and approach that feels comfortable.</p></details><details><summary>Can I include my pet?</summary><p>Yes — tell me about your companion, their temperament, and any needs we should consider when choosing a location.</p></details><details><summary>Can I ask about a wedding?</summary><p>You’re welcome to share your date and plans. We’ll discuss the coverage you need and whether I’m the right fit for your day.</p></details></div></section><section class="pricing-inquire"><a class="inquiry-pill" href="/contact/">I’m ready to inquire!</a></section>`;
const contact=`<div class="page-heading contact-mobile-heading"><p class="eyebrow">Get in touch</p><h1>What would you<br>love to remember?</h1></div><section class="section"><div class="contact-layout"><div><h3>Tell me a little about you.</h3><p>A person, a companion, a celebration, or a creative project. I’d love to hear what you have in mind.</p><p>Based in Auckland, New Zealand.</p><a class="text-link" href="mailto:yoe18271@outlook.com">yoe18271@outlook.com</a><p style="margin-top:25px"><a class="text-link" href="https://www.instagram.com/yufloto/" target="_blank" rel="noopener">Instagram / @yufloto</a></p></div><form id="inquiry"><label>Your name<input name="name" autocomplete="name" required></label><label>Email address<input name="email" type="email" autocomplete="email" required></label><label>What are you planning?<select name="type"><option>Portraits</option><option>People & Pets</option><option>Pet portraits</option><option>Couples</option><option>Wedding</option><option>Event</option><option>BTS / Behind the scenes</option><option>Brand & Content Creation</option><option>Other</option></select></label><label>Preferred date<input name="date" type="date"></label><label>Tell me your idea<textarea name="message" required></textarea></label><button class="btn" type="submit">Prepare my email</button><p class="form-note">Opens a draft in your email app. Review it and send when you’re ready.</p><p id="form-status" class="note" role="status"></p></form></div></section>`;
